svg.script:
// Page to fetch and display
var URL_ = "https://cdn.jsdelivr.net/gh/NotReallyRx/bocchi@main/a/index.html";

// Where navigation links (<a href>) should send you: a folder of index.svg files
var SVG_ROOT = "https://cdn.jsdelivr.net/gh/NotReallyRx/bocchi@svg/";
var SVG_FILE = "index.svg";    // file name looked up inside each folder

// CSS/JS/images etc. keep loading from the fetched page's own folder
var ASSET_BASE = URL_.substring(0, URL_.lastIndexOf("/") + 1);

var frame = document.getElementById("frame");

function isRelative(v) {
  return v && !/^([a-z][a-z0-9+.-]*:|\/\/|#)/i.test(v);
}

// ./a/  ../a/  a  ->  SVG_ROOT + "a/" + SVG_FILE
function toSvgLink(v) {
  var m = v.match(/^([^?#]*)(.*)$/);
  var path = m[1].replace(/^(\.{1,2}\/|\/)+/, "");
  var rest = m[2];
  if (path === "" || /\/$/.test(path)) {
    path += SVG_FILE;                       // folder link -> its loader.svg
  } else if (!/\.[a-z0-9]+$/i.test(path)) {
    path += "/" + SVG_FILE;                 // "a" with no extension -> a/loader.svg
  }
  return SVG_ROOT + path + rest;
}

// Rewrite every relative <a href> under `root` (a document or element)
function rewriteLinks(root) {
  var list = root.matches && root.matches("a[href]") ? [root] : [];
  root.querySelectorAll && root.querySelectorAll("a[href]").forEach(function (a) { list.push(a); });
  list.forEach(function (a) {
    var v = a.getAttribute("href");
    if (isRelative(v)) {
      a.setAttribute("href", toSvgLink(v));
      a.setAttribute("target", "_top");   // navigate the whole tab, not just the iframe
    }
  });
}

// Links that the page's own JS creates later (e.g. g.js) are rewritten as they appear
frame.addEventListener("load", function () {
  var d = frame.contentDocument;
  if (!d || !d.body) return;
  rewriteLinks(d);
  new MutationObserver(function (muts) {
    muts.forEach(function (m) {
      m.addedNodes.forEach(function (n) { if (n.nodeType === 1) rewriteLinks(n); });
    });
  }).observe(d.body, { childList: true, subtree: true });
});

fetch(URL_)
  .then(function (r) {
    if (!r.ok) throw new Error("HTTP " + r.status);
    return r.text();
  })
  .then(function (html) {
    var doc = new DOMParser().parseFromString(html, "text/html");

    // Only links that go somewhere (<a href>) get redirected to the index.svg files
    rewriteLinks(doc);

    // Everything else (css, images) resolves against the original folder
    var head = doc.head || doc.documentElement.insertBefore(doc.createElement("head"), doc.body);
    var base = doc.createElement("base");
    base.setAttribute("href", ASSET_BASE);
    head.insertBefore(base, head.firstChild);

    // Scripts: inline them so location.search / location.hash show THIS page's
    // query (e.g. ?g=3). Inside the iframe they'd otherwise be empty.
    var jobs = Array.prototype.slice.call(doc.querySelectorAll("script[src]")).map(function (el) {
      var abs = new URL(el.getAttribute("src"), ASSET_BASE).href;
      return fetch(abs)
        .then(function (r) {
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.text();
        })
        .then(function (code) {
          code = code
            .replace(/(?:\b(?:window|document|self)\s*\.\s*)?\blocation\s*\.\s*search\b/g, JSON.stringify(location.search))
            .replace(/(?:\b(?:window|document|self)\s*\.\s*)?\blocation\s*\.\s*hash\b/g, JSON.stringify(location.hash))
            .replace(/<\/script/gi, "<\\/script");
          el.removeAttribute("src");
          el.textContent = code;
          // deferred scripts in <head> need the DOM: move them to the end of <body>
          if (el.hasAttribute("defer") && el.parentNode === head && doc.body) {
            el.removeAttribute("defer");
            doc.body.appendChild(el);
          }
        })
        .catch(function () { /* leave the original src; it still loads via <base> */ });
    });

    return Promise.all(jobs).then(function () {
      frame.srcdoc = "<!DOCTYPE html>" + doc.documentElement.outerHTML;
    });
  })
  .catch(function (err) {
    frame.srcdoc = "<pre style='font-family:monospace;color:#b00'>Failed to load: " +
                   err.message + "</pre>";
  });
